-- Model storage migration for FreshScope Cloudflare D1 (SQLite).
-- model_baseline.models_json stores the complete Artificial Analysis snapshot, including source metadata and all model fields.
CREATE TABLE IF NOT EXISTS model_baseline (
  id INTEGER PRIMARY KEY CHECK (id = 1), -- Singleton key for the current benchmark baseline.
  source TEXT NOT NULL, -- Name of the benchmark data source.
  source_url TEXT NOT NULL, -- Link to the source page.
  retrieved_at TEXT NOT NULL, -- Date the benchmark snapshot was collected.
  models_json TEXT NOT NULL CHECK (json_valid(models_json)), -- Complete baseline JSON for self-service analysis.
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP -- Time this row was stored in D1.
);

-- Every successful manual refresh is retained so the application can compare consecutive directories.
CREATE TABLE IF NOT EXISTS model_catalog_snapshots (
  id INTEGER PRIMARY KEY AUTOINCREMENT, -- Snapshot identifier and ordering key.
  source TEXT NOT NULL, -- Directory source, currently Artificial Analysis public LLM leaderboard.
  retrieved_at TEXT NOT NULL, -- UTC time when the source directory was fetched.
  model_count INTEGER NOT NULL CHECK (model_count >= 0), -- Number of provider models in this snapshot.
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP -- Time this snapshot was stored in D1.
);

-- Normalized searchable fields plus each provider's complete original JSON object.
CREATE TABLE IF NOT EXISTS model_catalog_models (
  snapshot_id INTEGER NOT NULL REFERENCES model_catalog_snapshots(id) ON DELETE CASCADE, -- Parent snapshot.
  model_id TEXT NOT NULL, -- Provider model identifier.
  name TEXT NOT NULL, -- Display name from the source directory.
  provider TEXT NOT NULL CHECK (provider IN ('Anthropic', 'OpenAI')), -- Company selected from the provider model ID.
  created_at TEXT, -- Source creation date, when supplied.
  context_length INTEGER, -- Public context length, when supplied.
  input_price_usd_per_million_tokens REAL, -- Input token price normalized to USD per million tokens.
  output_price_usd_per_million_tokens REAL, -- Output token price normalized to USD per million tokens.
  raw_json TEXT NOT NULL CHECK (json_valid(raw_json)), -- Complete original provider model object.
  PRIMARY KEY (snapshot_id, model_id)
);

CREATE INDEX IF NOT EXISTS idx_model_catalog_snapshots_retrieved
  ON model_catalog_snapshots (retrieved_at DESC, id DESC);
CREATE INDEX IF NOT EXISTS idx_model_catalog_models_provider
  ON model_catalog_models (snapshot_id, provider, created_at DESC);

-- One-minute global cooldown prevents repeated public button clicks from creating excessive D1 snapshots.
CREATE TABLE IF NOT EXISTS model_catalog_sync_state (
  id INTEGER PRIMARY KEY CHECK (id = 1), -- Singleton state row.
  last_requested_at INTEGER NOT NULL DEFAULT 0 -- Unix time at which the most recent sync request began.
);
INSERT OR IGNORE INTO model_catalog_sync_state (id, last_requested_at) VALUES (1, 0);

